{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.derekslinz/meta-data-mcp",
  "description": "Query 88 open data APIs — government, science, finance, environment, and more.",
  "version": "2.7.0",
  "repository": {
    "url": "https://github.com/derekslinz/meta-data-mcp",
    "source": "github"
  },
  "packages": [
    {
      "registryType": "pypi",
      "identifier": "meta-data-mcp",
      "version": "2.7.0",
      "runtimeHint": "python",
      "transport": {
        "type": "sse",
        "url": "https://mcp.linzalytics.com/sse"
      }
    }
  ],
  "_meta": {
    "io.modelcontextprotocol.registry/publisher-provided": {
      "io.github.derekslinz": {
        "anonymous_access": "All tools are available without credentials. Some providers require a free API key set as an environment variable on the server side — the connecting client never handles keys.",
        "categories": [
          "open-data",
          "government",
          "science",
          "finance",
          "environment",
          "geospatial",
          "health",
          "law"
        ],
        "pitch": "One MCP server, 88 open data sources. Ask about GDP, earthquakes, court records, air quality, drug approvals, satellite imagery, or biodiversity — meta-data-mcp routes the request to the right API and returns structured data. Providers activate lazily so the default tool surface stays small; use opendata_providers_find to discover and opendata_providers_activate to unlock domain-specific tools on demand.",
        "example_calls": [
          "opendata_providers_find({ query: \"climate\" })  ->  ranked list of climate/weather providers",
          "opendata_providers_activate({ provider_id: \"global-world-bank\" })  ->  activates World Bank tools",
          "opendata_domains_list()  ->  full taxonomy of covered domains",
          "mcp_registry_search({ q: \"open data\" })  ->  discover other open-data MCP servers"
        ],
        "tools": [
          {
            "name": "opendata_providers_find",
            "description": "Semantic search across 88 providers — ranked matches with health scores and domain tags."
          },
          {
            "name": "opendata_providers_activate",
            "description": "Lazily activate a provider to expose its domain-specific tools without restarting the server."
          },
          {
            "name": "opendata_providers_deactivate",
            "description": "Deactivate a provider and remove its tools from the active surface."
          },
          {
            "name": "opendata_providers_list",
            "description": "List all available providers with metadata and health scores."
          },
          {
            "name": "opendata_providers_list_active",
            "description": "List currently activated providers and their exposed tools."
          },
          {
            "name": "opendata_domains_list",
            "description": "List all data domains covered (government, science, finance, environment, health, law, and more)."
          },
          {
            "name": "opendata_regions_list",
            "description": "List geographic regions with available providers."
          },
          {
            "name": "opendata_providers_describe",
            "description": "Full metadata for a provider: tools, endpoints, auth requirements, health score."
          },
          {
            "name": "opendata_health_snapshot",
            "description": "Real-time health scores for all providers — uptime, latency, error rates."
          },
          {
            "name": "opendata_explain_choice",
            "description": "Explain why a specific provider was ranked or selected for a query."
          },
          {
            "name": "opendata_plugins_draft",
            "description": "Generate a provider spec scaffold for a new open data API."
          },
          {
            "name": "opendata_plugins_create",
            "description": "Create and register a new provider plugin from a spec."
          },
          {
            "name": "mcp_registry_search",
            "description": "Search the official MCP server registry — meta-data-mcp can discover other MCP servers."
          },
          {
            "name": "mcp_registry_list",
            "description": "List all servers in the MCP registry, with pagination."
          }
        ]
      }
    }
  }
}
